function say(message){
  statusMessage=String(message||'');
  const composerStatus=document.querySelector('#composer-status');
  if(page==='chat'&&composerStatus){
    composerStatus.textContent=statusMessage;
    composerStatus.hidden=!statusMessage;
    notice.textContent='';notice.classList.remove('visible');
    return;
  }
  notice.textContent=statusMessage;notice.classList.toggle('visible',!!statusMessage)
}
