function bootError(code){const error=new Error(code);error.code=code;return error}
async function api(action,args={},options={}){
  if(preview)throw Error('Для сохранения открой Noema через Telegram. Здесь доступен только просмотр оформления.');
  const started=performance.now();
  const nativeAbort=typeof AbortController==='function',controller=nativeAbort?new AbortController():null,timeoutMs=Number(options.timeoutMs)||0;
  let timedOut=false;
  const abort=()=>{timedOut=true;controller?.abort?.()};
  options.signal?.addEventListener?.('abort',abort,{once:true});
  const timeout=timeoutMs?setTimeout(abort,timeoutMs):0;
  try{const initData=tg?.initData||window.NoemaBoot?.initData?.();if(!initData)throw bootError('INITDATA_MISSING');const request={method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:initData,action,args})};if(controller)request.signal=controller.signal;const pending=fetch('/api/v1/miniapp',request);const response=controller?await pending:await(timeoutMs?Promise.race([pending,new Promise((_,reject)=>setTimeout(()=>reject(bootError('API_TIMEOUT')),timeoutMs))]):pending);
   if(response.status===401||response.status===403)throw bootError('SESSION_EXPIRED');
   const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Нет соединения с Noema.');if(action==='state')window.NoemaBoot?.checkpoint?.('STATE_RECEIVED');return result.data}
  catch(error){if(timedOut||controller?.signal?.aborted)throw bootError(timeoutMs?'API_TIMEOUT':'REQUEST_ABORTED');throw error}
  finally{if(timeout)clearTimeout(timeout);options.signal?.removeEventListener?.('abort',abort);telemetry.record('ui_action_ms',performance.now()-started,{action})}
}
async function load(options={}){const boot=window.NoemaBoot,chatSnapshot=page==='chat'?window.NoemaChatScroll?.snapshot?.():null;data=await api('state',{},options);if(options.signal?.aborted)throw bootError('BOOT_TIMEOUT');boot?.checkpoint?.('SCREENS_INIT_START');try{stateLoadedAt=Date.now();window.NoemaTelemetryEnabled=Boolean(data.settings?.telemetry_enabled);window.NoemaRealtimeBeta?.setEnabled(Boolean(data.settings?.experimental_realtime),{wakeEnabled:Boolean(data.settings?.experimental_wake_enabled)}).catch(()=>{});window.NoemaChatScrollRestore=chatSnapshot}catch(error){boot?.reportFailure?.(error,'SCREENS_INIT_START');throw error}boot?.checkpoint?.('SCREENS_INIT_OK');try{render()}catch(error){boot?.reportFailure?.(error,'SCREENS_INIT_OK');throw error}if(document.querySelector('#content')?.firstElementChild)boot?.checkpoint?.('ROOT_RENDERED');if(page==='chat')await window.NoemaChatScroll?.whenSettled?.()}
function refreshStateOnResume(){if(preview||document.hidden||!stateLoadedAt||Date.now()-stateLoadedAt<750||stateRefreshPromise)return;stateRefreshPromise=load().catch(()=>{}).finally(()=>{stateRefreshPromise=null})}
function empty(text='Здесь пока тихо. Добавь первую запись.'){return `<div class="empty">${text}</div>`}
function card(title,body,target,name){return NoemaUI.card(title,body,target,name)}
function taskRows(items){return items.map(t=>`<div class="row"><button class="check ${t.status!=='open'?'done':''}" data-toggle="${t.id}" aria-label="Изменить статус задачи">${t.status!=='open'?'✓':''}</button><div class="body"><p>${esc(t.text)}</p><small>${date(t.due_date)}</small></div>${page==='tasks'?`<button class="delete" data-delete="delete_task" data-id="${t.id}" aria-label="Удалить задачу">×</button>`:''}</div>`).join('')||empty('Планы свободны. Чем займёмся?')}
function home(){
  const d=new Date(data.day+'T12:00:00');
  const pending=data.tasks.filter(t=>t.status==='open'&&(!t.due_date||t.due_date<=data.day));
  const upcoming=data.reminders.filter(r=>!r.acknowledged).sort((a,b)=>a.remind_at_utc.localeCompare(b.remind_at_utc))[0];
  const spent=data.expenses.filter(e=>e.kind!=='income').reduce((s,e)=>s+Number(e.amount),0);
  return `<section class="card hero"><div class="hero-content"><h3>ТВОЙ ДЕНЬ</h3><div class="hero-date"><span class="date-number">${d.getDate()}</span><p>${d.toLocaleDateString('ru-RU',{month:'long'})}<br>${d.toLocaleDateString('ru-RU',{weekday:'long'})}</p></div><p class="subtle" style="margin:18px 0 0">${pending.length?pending.length+' дел ждут твоего внимания':'Немного пространства для себя'}</p></div><div class="ambient-orb"></div></section>
  <div class="grid">${card('Задачи',taskRows(pending.slice(0,3)),'tasks')}${card('Следующее напоминание',upcoming?`<p class="amount">${new Date(upcoming.remind_at_utc).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:data.settings.timezone})}</p><p>${esc(upcoming.text)}</p><small>${date(upcoming.remind_at_utc)}</small>`:empty('Никаких сигналов. Всё спокойно.'),'reminders')}${card('Заметки',data.notes.slice(0,3).map(n=>`<p>${esc(n.title||n.text.slice(0,85))}</p>`).join('')||empty('Сохрани мысль — я запомню.'),'archive')}${card('Бюджет',`<small>Расходы · доступная история</small><p class="amount">${money(spent)}</p><small>${data.expenses.length} операций</small>`,'budget')}</div>`;
}
function archive(){
  const sources=[...data.notes.map(n=>({...n,type:'notes',label:'Заметка',name:n.title||n.text})),...data.files.map(f=>({...f,type:'files',label:f.mime_type?.startsWith('image/')?'Изображение':'Файл',name:f.original_name,text:f.summary}))];
  const items=sources.filter(x=>(filter==='all'||filter===x.type)&&`${x.name} ${x.text}`.toLowerCase().includes(search.toLowerCase()));
  return `<h1>Архив</h1><p class="subtle">Всё, что стоит сохранить.</p><input class="search" id="search" placeholder="Найти в заметках и файлах…" value="${esc(search)}"><div class="toolbar">${[['all','Всё'],['notes','Заметки'],['files','Файлы']].map(([key,label])=>`<button class="pill ${filter===key?'selected':''}" data-filter="${key}">${label}</button>`).join('')}<button class="secondary" data-form="note">＋ Заметка</button></div>${items.map(n=>`<article class="card"><div class="card-head"><h2>${esc(n.name?.slice(0,100))}</h2>${n.type==='notes'?`<button class="delete" data-delete="delete_note" data-id="${n.id}" aria-label="Удалить заметку">×</button>`:''}</div><p class="subtle">${esc(n.text)}</p><small>${n.label} · ${date(n.created_at)}</small></article>`).join('')||empty()}`;
}
