  this.buffer+=text;const out=[];let match;
  while((match=this.buffer.match(/^.*?[.!?…](?:\s+|$)/s))){const sentence=match[0].trim();this.buffer=this.buffer.slice(match[0].length);this.ready=[this.ready,sentence].filter(Boolean).join(' ');if(this.ready.length>=this.minChars){this.push(out,this.ready);this.ready=''}}
