  // Voice should start while the first sentence is still streaming instead of
  // waiting several seconds for terminal punctuation.  Cut only at a word
  // boundary and use this aggressive threshold for the first spoken chunk.
  if(!this.emitted&&combined.length>=this.firstChars){const cap=Math.min(combined.length,72);let cut=Math.max(combined.lastIndexOf(', ',cap),combined.lastIndexOf('; ',cap),combined.lastIndexOf(': ',cap),combined.lastIndexOf(' ',cap));if(cut<this.firstChars-8)cut=cap;this.push(out,combined.slice(0,cut+1));this.ready='';this.buffer=combined.slice(cut+1).trimStart()}
