 async toggle(){if(preview){say('Голос доступен при открытии через Telegram.');return}if(this.state==='recording')return this.stopRecording();if(this.state==='speaking'){this.speech.pause();this.setState('paused');return}if(this.state==='paused'){this.speech.resume();this.setState('speaking');return}if(this.state==='processing'){say('Запрос уже выполняется. Можно перейти на другой экран.');return}return this.startRecording()}
