document.addEventListener('pointerdown',e=>{const button=e.target.closest('[data-voice]');if(!button||!['speaking','paused'].includes(voiceController.state))return;clearTimeout(voiceLongPressTimer);voiceLongPressOrigin={id:e.pointerId,x:e.clientX,y:e.clientY};voiceLongPressTimer=setTimeout(async()=>{suppressVoiceTapUntil=performance.now()+700;voiceLongPressOrigin=null;window.NoemaHaptics.impact('medium');await voiceController.bargeIn()},550)},{passive:true});
