function openForm(name,values={},actionOverride='',titleOverride=''){const [title,action,fields]=forms[name];editAction=actionOverride||action;document.querySelector('#form-title').textContent=titleOverride||title;const fieldKeys=new Set(fields.map(x=>x[0]));const hidden=Object.entries(values).filter(([key])=>key.endsWith('_id')&&!fieldKeys.has(key)).map(([key,value])=>`<input type="hidden" name="${key}" value="${esc(value)}">`).join('');document.querySelector('#fields').innerHTML=fields.map(([key,label,type])=>{const value=values[key]??(name==='timezone'?data.settings.timezone:name==='briefing'?data.settings.briefing[key]||'':key==='priority'?'normal':'');const optional=['relationship','notes','due_date','city','title','birthday','projects','category','priority','age','home_city','current_location'].includes(key),numberAttrs=type==='number'?(key==='age'?'min="0" step="1"':'min="0.01" step="0.01"'):'';return `<label>${esc(label)}${type==='textarea'?`<textarea name="${key}" ${optional?'':'required'}>${esc(value)}</textarea>`:`<input name="${key}" type="${type}" ${numberAttrs} value="${esc(value)}" ${optional?'':'required'}>`}</label>`}).join('')+hidden;showDialog(document.querySelector('#editor'))}
function localDateTime(value){if(!value)return '';const d=new Date(value);const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function openEdit(type,id){let item,values,action,title,form;if(type==='task'){item=data.tasks.find(x=>x.id===id);values={text:item?.text,due_date:item?.due_date,priority:item?.priority,task_id:id};action='update_task';title='Изменить задачу';form='task'}if(type==='note'){item=data.notes.find(x=>x.id===id);values={title:item?.title,text:item?.text,note_id:id};action='update_note';title='Изменить заметку';form='note'}if(type==='reminder'){item=data.reminders.find(x=>x.id===id);values={text:item?.text,remind_at:localDateTime(item?.remind_at_utc),reminder_id:id};action='update_reminder';title='Изменить напоминание';form='reminder'}if(type==='expense'){item=(budgetData?.items||data.expenses).find(x=>x.id===id);values={amount:item?.amount,description:item?.description,category:item?.category,expense_id:id};action='update_expense';title='Изменить операцию';form=item?.kind==='income'?'income':'expense'}if(type==='person'){item=data.people.find(x=>x.id===id);values={name:item?.name,relationship:item?.relationship,birthday:item?.birthday,age:item?.age,home_city:item?.home_city,current_location:item?.current_location,projects:item?.projects,notes:item?.notes,person_id:id};action='update_person';title='Изменить человека';form='person'}if(type==='rule'){item=data.rules.find(x=>x.id===id);values={description:item?.description,rule_id:id};action='update_behavior_rule';title='Изменить правило';form='rule'}if(item)openForm(form,values,action,title)}
const mediaUrls=new Set(),thumbnailUrls=new Map(),unavailableThumbnails=new Set();
async function fetchStoredFile(id){const response=await fetch('/api/v1/miniapp',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:tg?.initData||'',action:'file',args:{id:Number(id)}})});if(!response.ok)throw Error('Файл недоступен');return response.blob()}
