function openExternalDownload(url,kind){try{if(tg?.openLink){tg.openLink(url);fetch('/api/v1/miniapp',{method:'POST',headers:{'Content-Type':'application/json'},keepalive:true,body:JSON.stringify({init_data:tg?.initData||'',action:'download_opened',args:{kind}})}).catch(()=>{});return}const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';link.style.display='none';document.body.append(link);link.click();link.remove()}catch{say('Не удалось открыть загрузку.')}}
async function downloadArtifact(artifactId){openExternalDownload(await requestDownloadTicket('artifact',artifactId),'artifact')}
async function hydrateMediaThumbnail(holder){const id=Number(holder.dataset.thumbnailFile||holder.dataset.avatarFile);if(!id||holder.dataset.loaded)return;holder.dataset.loaded='1';try{const url=await fetchThumbnail(id,holder.dataset.thumbnailVersion),img=new Image();img.alt='';img.decoding='async';img.onload=()=>holder.classList.add('loaded');img.src=url;holder.replaceChildren(img)}catch{holder.classList.add('thumbnail-unavailable');if(holder.dataset.avatarFile)holder.textContent='•'}}
let mediaThumbnailObserver;
function hydrateMediaThumbnails(){if(preview)return;const holders=document.querySelectorAll('[data-thumbnail-file]:not([data-loaded]),[data-avatar-file]:not([data-loaded])');if(!('IntersectionObserver'in window)){holders.forEach(hydrateMediaThumbnail);return}mediaThumbnailObserver||=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){mediaThumbnailObserver.unobserve(entry.target);hydrateMediaThumbnail(entry.target)}}),{rootMargin:'240px'});holders.forEach(holder=>mediaThumbnailObserver.observe(holder))}
async function hydrateAvatarImages(){hydrateMediaThumbnails()}
async function uploadPersonAvatar(personId,file){if(!file||!/^image\/(jpeg|png|webp|gif)$/i.test(file.type)||file.size>8*1024*1024){say('Выбери JPG, PNG, WebP или GIF до 8 МБ.');return}const form=new FormData();form.append('init_data',tg?.initData||'');form.append('person_id',String(personId));form.append('avatar',file,file.name||'avatar.jpg');busy=true;try{const response=await fetch('/api/v1/miniapp/person-avatar',{method:'POST',body:form}),result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Не удалось сохранить фото.');await load();say('Фото обновлено.')}catch(error){say(error.message)}finally{busy=false}}
function archiveItem(type,id){return type==='notes'?data.notes.find(item=>item.id===id):data.files.find(item=>item.id===id)}
let mediaViewerHistory=false,mediaViewerScrollY=0,closingMediaViewer=false,currentDetailFileId=0;
function closeArchivePreview(fromHistory=false){const dialog=document.querySelector('#archive-preview');if(!dialog?.open)return false;const restoreDetail=dialog.classList.contains('media-viewer')&&currentDetailFileId;closingMediaViewer=true;dialog.close();dialog.classList.remove('media-viewer');window.scrollTo({top:mediaViewerScrollY});if(mediaViewerHistory&&!fromHistory&&history.state?.noemaMediaViewer)history.back();mediaViewerHistory=false;closingMediaViewer=false;if(restoreDetail)setTimeout(()=>openFileDetail(currentDetailFileId),0);else currentDetailFileId=0;window.NoemaSyncBackButton?.();return true}
window.NoemaCloseArchivePreview=closeArchivePreview;
window.addEventListener('popstate',()=>closeArchivePreview(true));
document.querySelector('#archive-preview')?.addEventListener('cancel',event=>{if(event.currentTarget.classList.contains('media-viewer')){event.preventDefault();closeArchivePreview()}});
async function openArchivePreview(type,id){const item=archiveItem(type,id),dialog=document.querySelector('#archive-preview'),body=document.querySelector('#preview-body');if(!item||!dialog)return;const mime=String(item.mime_type||''),isImage=mime.startsWith('image/'),isPdf=mime==='application/pdf',url=(String(item.summary||item.text||'').match(/https?:\/\/\S+/)||[])[0]||'';document.querySelector('#preview-title').textContent=item.title||item.original_name||'Просмотр';dialog.classList.toggle('media-viewer',isImage);body.innerHTML=`<div class="preview-media">${isImage?'<div class="preview-loading">Загружаю изображение…</div>':icon(isPdf?'file':'notes')}</div><p>${esc(item.text||item.summary||'Описание отсутствует.')}</p><dl class="preview-meta"><div><dt>Тип</dt><dd>${esc(type==='notes'?'Заметка':mime||item.kind||'Файл')}</dd></div><div><dt>Дата</dt><dd>${date(item.created_at)}</dd></div>${item.person_media?.length?`<div><dt>Люди</dt><dd>${esc(item.person_media.map(x=>x.name).join(', '))}</dd></div>`:''}</dl>${url?`<a class="primary preview-open" href="${esc(url)}" target="_blank" rel="noopener">Открыть источник</a>`:''}${type==='files'&&!url?'<button class="secondary preview-open" type="button" data-preview-download>Открыть файл</button>':''}`;mediaViewerScrollY=window.scrollY;showDialog(dialog);if(isImage&&!mediaViewerHistory&&history?.pushState){history.pushState({noemaMediaViewer:true},'');mediaViewerHistory=true}if(isImage&&!preview){try{const blob=await fetchStoredFile(id),objectUrl=URL.createObjectURL(blob);mediaUrls.add(objectUrl);body.querySelector('.preview-media').innerHTML=`<img src="${objectUrl}" alt="${esc(item.original_name||'Изображение')}">`}catch{body.querySelector('.preview-media').textContent='Изображение недоступно.'}}body.querySelector('[data-preview-download]')?.addEventListener('click',async()=>{try{openBlobInNewContext(await fetchStoredFile(id),item.original_name||'file')}catch(error){say(error.message)}})}
async function openFileDetail(id){const item=data.files.find(file=>file.id===Number(id)),dialog=document.querySelector('#archive-preview'),body=document.querySelector('#preview-body');if(!item||!dialog)return;currentDetailFileId=item.id;dialog.classList.remove('media-viewer');document.querySelector('#preview-title').textContent='Файл';const image=String(item.mime_type||'').startsWith('image/'),linked=new Set((item.person_media||[]).map(link=>Number(link.person_id))),candidates=data.people.filter(person=>!linked.has(Number(person.id)));body.innerHTML=`<button class="preview-media detail-preview" type="button" data-detail-open>${image?'<span class="preview-loading">Загружаю превью…</span>':icon('file')}</button><h3>${esc(item.original_name||'Файл')}</h3><textarea class="file-description" data-file-description placeholder="Добавить описание…">${esc(item.description||item.summary||'')}</textarea><dl class="preview-meta"><div><dt>Тип</dt><dd>${esc(item.mime_type||item.kind||'Файл')}</dd></div><div><dt>Создан</dt><dd>${date(item.created_at)}</dd></div>${item.person_media?.length?`<div><dt>Люди</dt><dd>${item.person_media.map(link=>`<button class="secondary" data-unlink-person="${link.person_id}">${esc(link.name)} ×</button>${link.relation_type==='photo'?`<button class="secondary" data-profile-person="${link.person_id}">Сделать фото профиля</button>`:''}`).join(' ')}</dd></div>`:''}</dl>${image&&candidates.length?`<label class="subtle">Связать с человеком <select data-link-person><option value="">Выбери человека</option>${candidates.map(person=>`<option value="${person.id}">${esc(person.name)}</option>`).join('')}</select></label>`:''}<div class="toolbar"><button class="primary" data-file-save>Сохранить описание</button><button class="secondary" data-detail-open>Открыть</button><button class="secondary" data-file-download>Скачать</button><button class="secondary" data-file-delete>Удалить</button></div>`;showDialog(dialog);if(image&&!preview)try{const url=await fetchThumbnail(item.id,item.thumbnail_version);body.querySelector('.detail-preview').innerHTML=`<img src="${url}" alt="${esc(item.original_name||'Изображение')}">`}catch{body.querySelector('.detail-preview').textContent='Превью недоступно.'}}
function voicePreferenceValues(){const current=data.settings?.voice_preferences||{};return {gender:document.querySelector('#voice-choice')?.value||current.gender||'male'}}
async function previewVoice(){const prefs=voicePreferenceValues(),slots=data.settings?.voice_runtime||{},current=data.settings?.voice_preferences||{},voice=prefs.gender==='female'?slots.tts_female_voice:slots.tts_male_voice;if(preview||slots.tts_provider==='browser'){if(!preview)await api('voice_preferences',prefs);const utterance=new SpeechSynthesisUtterance('Привет. Так будет звучать голос Noema.');utterance.lang='ru-RU';utterance.voice=browserVoice(voice);utterance.rate=Number(current.speed)||1;utterance.pitch=Number(current.pitch)||1;utterance.volume=Number(current.volume)||1;window.speechSynthesis?.cancel();window.speechSynthesis?.speak(utterance);return}await api('voice_preferences',prefs);await load();const response=await fetch('/api/v1/miniapp/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:tg?.initData||'',text:'Привет. Так будет звучать голос Noema.'})});if(!response.ok)throw Error('Предпрослушивание недоступно.');new Audio(URL.createObjectURL(await response.blob())).play()}
async function mutate(action,args){if(busy)return;busy=true;try{await api(action,args);await load();if(page==='budget')await loadBudget();window.NoemaHaptics.notification('success');say('')}catch(e){window.NoemaHaptics.notification('error');say(e.message)}finally{busy=false}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[role=button]');if(!b)return;
  if(b.dataset.page&&!(window.homeEditing&&b.closest('.home-grid')))go(b.dataset.page);
  if(b.id==='record')await recordVoice(b);
  if(b.dataset.filter){const changed=filter!==b.dataset.filter;filter=b.dataset.filter;if(changed)window.NoemaHaptics.selection();render()}
  if(b.dataset.form)openForm(b.dataset.form);
  if(b.dataset.adminConfig)openAdminRuntimeConfig(b.dataset.adminConfig);
  if(b.dataset.adminReset)await mutate('admin_runtime_config_reset',{field:b.dataset.adminReset});
  if(b.dataset.edit)openEdit(b.dataset.edit,Number(b.dataset.id));
  if(b.dataset.toggle)await mutate('task_toggle',{id:Number(b.dataset.toggle)});
  if(b.dataset.reminder)await mutate('reminder_done',{id:Number(b.dataset.reminder)});
  if(b.dataset.archiveOpen){const [type,id]=b.dataset.archiveOpen.split(':');if(type==='files')await openFileDetail(Number(id));else await openArchivePreview(type,Number(id))}
  if(b.dataset.artifactDownload)try{await downloadArtifact(b.dataset.artifactDownload)}catch(error){say(error.message)}
  if(b.hasAttribute('data-detail-open'))await openArchivePreview('files',currentDetailFileId)
  if(b.hasAttribute('data-file-download'))try{openExternalDownload(await requestDownloadTicket('file',currentDetailFileId),'file')}catch(error){say(error.message)}
  if(b.hasAttribute('data-file-save'))try{await api('file_update',{id:currentDetailFileId,description:document.querySelector('[data-file-description]')?.value||''});await load();await openFileDetail(currentDetailFileId);say('Описание сохранено.')}catch(error){say(error.message)}
  if(b.hasAttribute('data-file-delete')&&confirm('Удалить файл без возможности восстановления?'))try{await api('file_delete',{id:currentDetailFileId});closeArchivePreview();await load();say('Файл удалён.')}catch(error){say(error.message)}
  if(b.dataset.unlinkPerson&&confirm('Отвязать файл от человека?'))try{await api('person_media_unlink',{person_id:Number(b.dataset.unlinkPerson),file_id:currentDetailFileId});await load();await openFileDetail(currentDetailFileId)}catch(error){say(error.message)}
  if(b.dataset.profilePerson)try{await api('person_media_profile',{person_id:Number(b.dataset.profilePerson),file_id:currentDetailFileId});await load();await openFileDetail(currentDetailFileId)}catch(error){say(error.message)}
  if(b.dataset.avatarRemove&&confirm('Удалить фото профиля?'))await mutate('person_avatar_remove',{person_id:Number(b.dataset.avatarRemove)});
  if(b.hasAttribute('data-preview-close'))closeArchivePreview();
  if(b.hasAttribute('data-voice-preview'))try{await previewVoice()}catch(error){say(error.message)}
  if(b.dataset.delete&&confirm('Удалить эту запись?')){const keys={delete_note:'note_id',delete_task:'task_id',delete_person:'person_id',delete_expense:'expense_id',delete_reminder:'reminder_id',delete_behavior_rule:'rule_id'};await mutate(b.dataset.delete,{[keys[b.dataset.delete]]:Number(b.dataset.id)})}
  if(b.id==='cancel')document.querySelector('#editor').close();
  if(b.id==='clear-chat'&&confirm('Очистить историю диалога?'))await mutate('clear_history',{});
});
document.addEventListener('change',async e=>{if(e.target.matches('[data-link-person]')&&e.target.value)try{await api('person_media_link',{person_id:Number(e.target.value),file_id:currentDetailFileId});await load();await openFileDetail(currentDetailFileId)}catch(error){say(error.message)}if(e.target.id==='voice-choice')await mutate('voice_preferences',voicePreferenceValues());if(e.target.id==='mode')await mutate('mode',{mode:e.target.value});if(e.target.id==='brief-enabled')await mutate('set_briefing_preferences',{enabled:e.target.checked});if(e.target.id==='brief-time')await mutate('set_briefing_preferences',{time:e.target.value});if(e.target.id==='realtime-beta'){await mutate('set_experimental_realtime',{enabled:e.target.checked});window.NoemaRealtimeBeta?.setEnabled(e.target.checked,{wakeEnabled:Boolean(data.settings?.experimental_wake_enabled)}).catch(()=>say('Не удалось загрузить Beta-режим.'))}if(e.target.id==='wake-word-beta'){await mutate('set_experimental_wake',{enabled:e.target.checked});window.NoemaRealtimeBeta?.setWakeEnabled?.(e.target.checked)}if(e.target.matches('[data-person-avatar]'))await uploadPersonAvatar(Number(e.target.dataset.personAvatar),e.target.files?.[0]);if(e.target.matches('[data-people-overflow]')&&e.target.value){peopleFilter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.matches('[data-runtime-range]')){const output=e.target.parentElement?.querySelector('[data-range-output]');if(output)output.textContent=Number(e.target.value).toFixed(2)}});
document.querySelector('#edit-form').addEventListener('submit',async e=>{e.preventDefault();const args=Object.fromEntries(new FormData(e.target));if(args.amount)args.amount=Number(args.amount);await mutate(editAction,args);if(!notice.textContent)document.querySelector('#editor').close()});
document.querySelector('#archive-preview')?.addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});
function rememberCanonicalChat(userText,answer,event){const userId=event?.canonical_user_message_id,assistantId=event?.canonical_message_id;if(userId&&!data.history.some(item=>item.message_id===userId))data.history.push({message_id:userId,role:'user',content:userText,artifacts:[]});if(assistantId&&!data.history.some(item=>item.message_id===assistantId))data.history.push({message_id:assistantId,role:'assistant',content:answer,artifacts:event?.artifacts||[]});data.history=data.history.slice(-50)}
async function streamChat(text,options={}){
 const response=await fetch('/api/v1/miniapp/chat-stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({init_data:tg?.initData||'',text}),signal:options.signal});if(!response.ok)throw Error(await response.text()||'Не удалось получить ответ.');
 let thread=options.render===false?null:document.querySelector('.chat');let bubble=null,renderFrame=0,pending='',localVisibleText='',terminal=null,firstVisible=false;
 const ensureBubble=()=>{if(!thread||bubble)return bubble;thread.querySelector('.empty')?.remove();bubble=document.createElement('div');bubble.className='bubble assistant streaming';bubble.dataset.messageKey=`pending-assistant-${globalThis.crypto?.randomUUID?.()||Date.now()}`;window.NoemaChatScroll?.appendBubble(bubble);window.NoemaChatScroll?.incoming({newMessage:true});return bubble};
 const flush=()=>{renderFrame=0;if(!bubble?.isConnected)return;bubble.innerHTML=`<span class="message-text">${renderAssistantContent(localVisibleText)}</span>`;window.NoemaChatScroll?.incoming()};
 const consume=event=>{if(event.type==='job')options.onJob?.(event.job_id);if(event.type==='state'){if(options.onState)options.onState(event);else window.NoemaRuntimeState.applyEvent(event)}if(event.type==='progress')window.NoemaRuntimeState.transition('REQUESTING',{text:event.text});if(event.type==='delta'){if(!firstVisible){firstVisible=true;window.NoemaRuntimeState.transition('STREAMING')}localVisibleText+=String(event.text||'');if(ensureBubble()&&!renderFrame)renderFrame=requestAnimationFrame(flush);options.onDelta?.(event.text)}if(event.type==='speech_delta')options.onSpeechDelta?.(String(event.text||''));if(event.type==='done')terminal=event;if(event.type==='cancelled')throw new DOMException('Generation stopped','AbortError');if(event.type==='error')throw Error('Не удалось получить ответ. Попробуй ещё раз.')};
 const reader=response.body.getReader(),decoder=new TextDecoder();while(true){const {value,done}=await reader.read();pending+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=pending.split('\n');pending=lines.pop()||'';for(const line of lines)if(line.trim())consume(JSON.parse(line));if(done)break}if(pending.trim())consume(JSON.parse(pending));if(renderFrame){cancelAnimationFrame(renderFrame);flush()}
 const canonical=String(terminal?.text??localVisibleText);if(canonical!==localVisibleText){const missing=canonical.startsWith(localVisibleText)?canonical.slice(localVisibleText.length):'';localVisibleText=canonical;if(missing)options.onDelta?.(missing)}if(!thread&&terminal?.artifacts?.length&&page==='chat')thread=document.querySelector('.chat');if(thread&&(canonical||terminal?.artifacts?.length)){ensureBubble();bubble.innerHTML=`<span class="message-text">${renderAssistantContent(canonical)}</span>${artifactCards(terminal?.artifacts||[])}`;bubble.classList.remove('streaming');if(terminal?.canonical_message_id){bubble.dataset.messageId=String(terminal.canonical_message_id);bubble.dataset.messageKey=`message-${terminal.canonical_message_id}`}}if(options.pendingUser&&terminal?.canonical_user_message_id){options.pendingUser.classList.remove('pending');options.pendingUser.dataset.messageId=String(terminal.canonical_user_message_id);options.pendingUser.dataset.messageKey=`message-${terminal.canonical_message_id}`}rememberCanonicalChat(options.userText||text,canonical,terminal);options.onDone?.(terminal,canonical);return canonical
}
let chatSubmitting=false,chatSubmitGeneration=0;
function resizeChatInput(input){if(!input)return;const snapshot=window.NoemaChatScroll?.snapshot?.();input.style.height='auto';input.style.height=Math.min(input.scrollHeight,122)+'px';window.NoemaChatScroll?.layoutChanged?.(snapshot)}
document.addEventListener('input',e=>{if(e.target.id==='chat-input')resizeChatInput(e.target)});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();e.target.form?.requestSubmit()}});
document.addEventListener('submit',async e=>{if(e.target.id!=='chat-form')return;e.preventDefault();if(chatSubmitting&&!['speaking','paused'].includes(voiceController.state))return;const input=document.querySelector('#chat-input'),text=input.value.trim();if(!text)return;const submission=++chatSubmitGeneration;chatSubmitting=true;input.value='';resizeChatInput(input);try{await voiceController.ask(text)}catch(err){if(submission===chatSubmitGeneration){say(err.message);input.value=text;resizeChatInput(input)}}finally{if(submission===chatSubmitGeneration)chatSubmitting=false}});
